  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.purpose.543bf92": "Read the version information of the unified CDP portal",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.description.06dbbb1": "This interface transparently transmits the CDP version information of the current active target, which is suitable for detecting whether the debugging entrance is available before attaching.",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.description.e473cd5": "Returns the version information of the current active target",
