  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.purpose.ffba70e": "Read the target list currently exposed by the unified CDP portal",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.description.4574aca": "Used by Playwright, Puppeteer, or diagnostic tools to view the currently active target",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.description.dff7260": "Returns the target list of the currently active instance",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.purpose.fb490df": "Take over the current active instance through the unified WebSocket portal",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.description.226e218": "This WebSocket entry is actually used during attach. External tools usually get /json/version or /json/list first, and then connect to the corresponding websocketDebuggerUrl.",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.message.ba0c174": "const browser = await chromium.connectOverCDP(\"{0}\");\n// Or press the webSocketDebuggerUrl returned by /json/list to connect to the specific page target",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.message.cdbcca8": "Enter the standard Chrome DevTools Protocol message flow after a successful WebSocket handshake.",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.description.1d62380": "WebSocket upgrade successful",
  "browser.pages.launchApiDocs.structuredApiDocs.runtimeEndpoints.message.a8330ee": "Adjust runtime/session first, and then connect to WS",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.intro.0f1c64b": "This page only provides an overview of instance management and startup capabilities. First complete the configuration through the instance interface, and then press launchCode or selector to start the instance.",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.message.ad6b4c3": "/api/profiles is responsible for instance addition, deletion, modification and query",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.message.80c0dd0": "/api/launch is responsible for launching",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.message.7d84c50": "Details can only be entered from \"View Details\" in the form",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.intro.f454b29": "This page lists only runtime control and unified CDP entries. The external orchestration side first confirms active / session, and then decides whether to attach or stop.",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.message.88ca460": "runtime/session is used to prepare before taking over",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.message.8b273c0": "runtime/status / runtime/stop all work according to selector",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.message.72a1ea2": "CDP details are only entered from the form",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.intro.ddf0703": "This page only lists public entries related to automation scripts. Check the script list first, then check details, execute the script, and review the running records as needed.",
  "browser.pages.launchApiDocs.structuredApiDocs.sections.message.3c92e48": "Check the list first, then check the details as needed",
